<div class="heading"><div><h1>Your mailboxes</h1><p>Signed in as <?= htmlspecialchars($user['email']) ?></p></div><a class="button" href="/mail">Open webmail</a><?php if($user['role']==='admin'): ?><a class="button secondary" href="/admin/mailboxes">Manage mailboxes</a><?php endif; ?></div><?php if(!$mailboxes): ?><section class="panel"><p>No mailboxes have been assigned to your account.</p></section><?php else: ?><div class="table-wrap"><table><thead><tr><th>Email</th><th>Name</th><th>Status</th><th>Created</th></tr></thead><tbody><?php foreach($mailboxes as $m): ?><tr><td><?= htmlspecialchars($m['email']) ?></td><td><?= htmlspecialchars($m['display_name']) ?></td><td><span class="status"><?= htmlspecialchars($m['status']) ?></span></td><td><?= htmlspecialchars($m['created_at']) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?><section class="panel"><h2>Mail client settings</h2><p>Use these settings in an external mail client. This application does not host SMTP or IMAP services.</p><table><tbody><tr><th>SMTP</th><td><?= htmlspecialchars($settings['smtp_host']) ?>:<?= htmlspecialchars($settings['smtp_port']) ?> (<?= htmlspecialchars($settings['smtp_encryption']) ?>)</td></tr><tr><th>IMAP</th><td><?= htmlspecialchars($settings['imap_host']) ?>:<?= htmlspecialchars($settings['imap_port']) ?> (<?= htmlspecialchars($settings['imap_encryption']) ?>)</td></tr></tbody></table></section>
